/* PaKuWord – polska paczka dzienna 2026-11-26: nowa dziedzina Sztuka (30) + 30 haseł w istniejących dziedzinach */
window.PW_CONTENT = window.PW_CONTENT || {};
window.PW_CONTENT.pl = (window.PW_CONTENT.pl || []).concat([
/* ---------- SZTUKA ---------- */
{id:"art_perspective",cat:"art",t:"Perspektywa",
 s:"Sposób rysowania i malowania, dzięki któremu płaski obraz sprawia wrażenie głębi i odległości.",
 l:"W perspektywie linearnej równoległe linie, na przykład krawędzie drogi albo rząd domów, rysuje się tak, by zbiegały się w jednym punkcie na linii horyzontu, zwanym punktem zbiegu. Przedmioty, które mają być dalej, rysuje się coraz mniejsze. Artyści stosują też perspektywę powietrzną: odległe wzgórza malują jaśniej, bardziej niebiesko i mniej ostro, tak jak widzimy je przez powietrze. Perspektywa to zestaw zasad rysunku, a nie styl, i wielu artystów świadomie ją łamie.",
 x:"Na jej rysunku ulicy wszystkie dachy prowadzą do jednego punktu zbiegu pośrodku.",
 f:"Odkrycie zasad perspektywy linearnej przypisuje się florenckiemu architektowi Filippowi Brunelleschiemu na początku piętnastego wieku, a Leon Battista Alberti opisał je w traktacie „O malarstwie” z 1435 roku.",
 js:"Sposób rysowania, dzięki któremu rzeczy wyglądają na bliskie albo dalekie.",
 jl:"Kiedy patrzysz na długą drogę, jej brzegi daleko jakby się do siebie zbliżają, a drzewa na końcu są malutkie. Artyści przenoszą to na papier: to, co daleko, rysują mniejsze, a linie schodzą się w jednym punkcie. To właśnie perspektywa.",
 jx:"Maja narysowała tory, które robiły się coraz węższe, aż spotkały się w jednej kropce."},
{id:"art_chiaroscuro",cat:"art",t:"Światłocień",
 s:"Mocny kontrast światła i cienia na obrazie, który modeluje kształty i dodaje scenie dramatyzmu.",
 l:"Malując światłocieniem, artysta mocno oświetla jedne części sceny, a inne pogrąża w głębokim mroku. Dzięki temu twarze i ciała wydają się wypukłe i bryłowate, a obraz może być napięty, tajemniczy albo teatralny. Włoski malarz Caravaggio posunął ten efekt tak daleko, że jego postacie zdają się wychodzić z ciemności, a Rembrandt sprawiał, że twarze na jego obrazach jakby świeciły. Z tej samej zasady korzystają rysunek, fotografia i oświetlenie filmowe.",
 x:"Świeca na obrazie oświetla tylko twarze dzieci – to piękny przykład światłocienia.",
 f:"W wielu językach używa się włoskiej nazwy chiaroscuro, która łączy słowa chiaro, czyli jasny, i scuro, czyli ciemny.",
 js:"Bardzo jasne światło i bardzo ciemny cień na jednym obrazie.",
 jl:"Wyobraź sobie, że świecisz latarką na twarz w ciemnym pokoju. Jedna strona jest jasna, druga w cieniu. Niektórzy malarze uwielbiali ten widok i malowali mocne światło obok głębokiej ciemności. Ich obrazy wyglądają przez to prawie jak prawdziwe i trochę magicznie.",
 jx:"Zrobiliśmy zdjęcia ze światłocieniem, używając latarki w zaciemnionym pokoju."},
{id:"art_fresco",cat:"art",t:"Fresk",
 s:"Malowidło ścienne wykonane farbą na świeżym, mokrym tynku wapiennym, dzięki czemu kolor staje się częścią ściany.",
 l:"W prawdziwym fresku malarz rozrabia pigmenty z wodą i nakłada je na tynk, który jest jeszcze wilgotny. Gdy tynk wysycha, zachodzi reakcja chemiczna, która wiąże barwę z powierzchnią, dlatego freski są bardzo trwałe. Tynk schnie w ciągu kilku godzin, więc artysta przygotowuje tylko taki fragment, jaki zdąży namalować danego dnia, a granice tych dziennych porcji czasem widać do dziś. Farba położona później na suchy tynk to technika secco, która łatwiej się łuszczy.",
 x:"Stara kaplica słynie z fresków przedstawiających świętych i anioły.",
 f:"Michał Anioł malował sklepienie Kaplicy Sykstyńskiej w Rzymie techniką fresku w latach 1508–1512.",
 js:"Obraz namalowany prosto na mokrej ścianie.",
 jl:"Niektórzy malarze malowali od razu na ścianach i sufitach. Rozprowadzali mokry tynk, gładki jak pasta, i malowali na nim, zanim wysechł. Kiedy tynk wysychał, kolory stawały się częścią ściany, więc takie obrazy przetrwały setki lat.",
 jx:"We Włoszech widzieliśmy na suficie kościoła fresk, który ma pięćset lat."},
{id:"art_primary_colours",cat:"art",t:"Barwy podstawowe",
 s:"Kilka barw, z których można zmieszać wiele innych, ale których samych nie da się uzyskać przez mieszanie.",
 l:"W tradycyjnym malarstwie barwami podstawowymi są czerwień, żółć i błękit, a zmieszanie dwóch z nich daje barwy pochodne: pomarańczową, zieloną i fioletową. To, które barwy są podstawowe, zależy jednak od sposobu tworzenia koloru. Ekrany tworzą kolor ze światła i ich barwy podstawowe to czerwona, zielona i niebieska; wszystkie trzy razem dają biel. Drukarki mieszają farby, które pochłaniają światło, i używają barw cyjan, magenta i żółtej. Żadne trzy farby nie dadzą wszystkich kolorów, jakie widzimy.",
 x:"Z samych trzech barw podstawowych klasa zmieszała całą tęczę kolorów.",
 f:"Drukarki dodają do cyjanu, magenty i żółtej czarny tusz, dlatego system nazywa się CMYK; litera K pochodzi od angielskiego key, drukarskiej nazwy płyty z czernią.",
 js:"Kolory, z których można zmieszać mnóstwo innych.",
 jl:"W twoich farbkach czerwony, żółty i niebieski są wyjątkowe. Nie zrobisz ich przez mieszanie, ale możesz z nich zrobić nowe kolory. Żółty z niebieskim daje zielony, czerwony z żółtym pomarańczowy, a czerwony z niebieskim fioletowy.",
 jx:"Zuzia zmieszała żółty z niebieskim i krzyknęła: Zrobiłam zielony!"},
{id:"art_complementary",cat:"art",t:"Barwy dopełniające",
 s:"Pary barw leżące naprzeciw siebie na kole barw, na przykład niebieska i pomarańczowa.",
 l:"Na kole barw każdy kolor ma swoje przeciwieństwo: czerwień i zieleń, błękit i pomarańcz, żółć i fiolet. Barwy dopełniające położone obok siebie wzajemnie się wzmacniają i wydają się jaśniejsze, co artyści i projektanci wykorzystują, by coś się wyróżniało. Zmieszane jako farby przygaszają się nawzajem do brązów i szarości, co przydaje się, gdy jakiś kolor jest zbyt krzykliwy. Na wielu plakatach filmowych widać połączenie pomarańczu z błękitem.",
 x:"Pomarańczowa łódka wyraźnie odcina się od niebieskiego morza, bo to barwy dopełniające.",
 f:"Isaac Newton ułożył barwy widma w okrąg w książce „Optyka” wydanej w 1704 roku – to jedna z pierwszych postaci koła barw.",
 js:"Dwa przeciwne kolory, które przy sobie wyglądają jaśniej.",
 jl:"Niektóre kolory są jak najlepsi przyjaciele, którzy są zupełnymi przeciwieństwami, na przykład niebieski i pomarańczowy albo czerwony i zielony. Kiedy stoją obok siebie, oba wyglądają jeszcze jaśniej. Dlatego czerwone jabłko tak błyszczy wśród zielonych liści.",
 jx:"Namalowałem fioletowego motyla na żółtym kwiatku, żeby było go dobrze widać."},
{id:"art_still_life",cat:"art",t:"Martwa natura",
 s:"Obraz przedstawiający nieruchome przedmioty, na przykład owoce, kwiaty, butelki czy książki.",
 l:"Martwa natura to ułożone na stole lub półce zwykłe rzeczy, na których artysta bada kształty, kolory, faktury i padanie światła. Ponieważ przedmioty się nie ruszają, martwa natura jest klasycznym ćwiczeniem w nauce rysunku i malarstwa. W siedemnastym wieku malarze niderlandzcy uczynili z niej ważny gatunek i malowali lśniące owoce, szkło i kwiaty z niezwykłą dokładnością. Niektóre martwe natury kryją przesłanie: więdnący kwiat czy dopalona świeca przypominają, że czas płynie.",
 x:"Na zadanie z plastyki narysował martwą naturę z czajniczkiem, dwiema cytrynami i łyżeczką.",
 f:"Polska nazwa to kalka francuskiego nature morte, a angielskie still life pochodzi od niderlandzkiego stilleven, czyli ciche, nieruchome życie.",
 js:"Obraz rzeczy, które się nie ruszają, na przykład owoców albo kwiatów.",
 jl:"Martwa natura to obraz przedmiotów, które spokojnie leżą, na przykład jabłek w misce, kwiatów w wazonie albo pary butów. Artyści je lubią, bo rzeczy się nie ruszają i można się im przyglądać tak długo, jak trzeba.",
 jx:"Nasza klasa namalowała martwą naturę z dynią, trzema jabłkami i dzbankiem."},
{id:"art_self_portrait",cat:"art",t:"Autoportret",
 s:"Portret, który artysta wykonał, przedstawiając samego siebie.",
 l:"Tworząc autoportret, artyści zwykle patrzyli w lustro, dlatego na wielu autoportretach twarz jest odwrócona, a oczy patrzą prosto na widza. Autoportret pozwala ćwiczyć bez płacenia modelowi, ale jest też sposobem pokazania, jak artysta widzi samego siebie, swój nastrój, zawód czy miejsce w świecie. Niektórzy malowali ich dziesiątki przez całe życie, więc możemy zobaczyć, jak się starzeli. Zdjęcie samego siebie zrobione z ręki nazywamy dziś selfie.",
 x:"Na autoportretach Fridy Kahlo często widać rośliny i zwierzęta.",
 f:"Albrecht Dürer narysował autoportret srebrnym rysikiem, gdy miał około trzynastu lat, w 1484 roku; to jeden z najstarszych zachowanych autoportretów dziecka w sztuce europejskiej.",
 js:"Obraz, na którym artysta przedstawia samego siebie.",
 jl:"Autoportret to twój portret, który robisz sam. Artyści często malowali, patrząc w lustro. Możesz narysować swoją twarz, ulubione ubranie albo coś, co kochasz, na przykład swojego psa czy piłkę.",
 jx:"Na moim autoportrecie trzymam kota i mam na głowie żółtą czapkę."},
{id:"art_impressionism",cat:"art",t:"Impresjonizm",
 s:"Kierunek w malarstwie, który narodził się we Francji w dziewiętnastym wieku i starał się uchwycić światło, kolor i ulotną chwilę.",
 l:"Impresjoniści, tacy jak Claude Monet, Pierre-Auguste Renoir, Camille Pissarro czy Berthe Morisot, często malowali w plenerze, szybko, widocznymi plamkami koloru. Mniej obchodziły ich szczegóły, bardziej to, jak scena wyglądała w danym momencie: słońce na wodzie, mgła na dworcu, cienie niebieskie lub fioletowe zamiast czarnych. Początkowo wielu krytyków uważało ich obrazy za niedokończone. Dziś impresjonizm należy do najpopularniejszych stylów w muzeach.",
 x:"Z bliska obraz wygląda jak bezładne plamki, ale z drugiego końca sali widać słoneczny impresjonistyczny ogród.",
 f:"Nazwa wzięła się od obrazu Moneta „Impresja, wschód słońca”; krytyk użył tego słowa złośliwie po pierwszej wystawie grupy w Paryżu w 1874 roku.",
 js:"Malowanie szybkimi plamkami koloru, żeby pokazać światło i chwilę.",
 jl:"Niektórzy malarze we Francji wychodzili na dwór i malowali bardzo szybko, zanim słońce się przesunęło i zmieniło światło. Ich pociągnięcia pędzla wyglądają jak małe plamki. Z bliska jest bałagan, ale gdy się cofniesz, zobaczysz lśniącą wodę, kwiaty czy chmury.",
 jx:"Malowaliśmy szkolny ogród jak impresjoniści – szybko, zanim przyszły chmury."},
{id:"art_cubism",cat:"art",t:"Kubizm",
 s:"Kierunek w sztuce z początku dwudziestego wieku, który rozbija przedmioty na geometryczne bryły i pokazuje je z kilku stron naraz.",
 l:"Kubizm stworzyli w Paryżu Pablo Picasso i Georges Braque około 1907 roku. Zamiast malować gitarę czy twarz z jednego miejsca, rozkładali je na płaskie płaszczyzny i kąty i pokazywali różne strony jednocześnie, jakby widz obchodził przedmiot dookoła. Kolory były początkowo stonowane, żeby uwaga skupiała się na budowie. Kubizm zmienił sposób myślenia o przestrzeni i otworzył drogę sztuce abstrakcyjnej, kolażowi i dużej części nowoczesnego projektowania.",
 x:"Na kubistycznym portrecie nos kobiety widać z profilu, a oba oczy z przodu.",
 f:"Duży obraz Picassa „Panny z Awinionu”, ukończony w 1907 roku, uważa się często za zapowiedź kubizmu.",
 js:"Sztuka, w której rzeczy wyglądają jak klocki i figury, widziane z wielu stron naraz.",
 jl:"Kubiści pytali: dlaczego malować coś tylko z jednej strony? Pokazywali więc przód i bok jednocześnie, używając wielu kątów i kształtów. Twarz mogła mieć nos z boku i dwoje oczu patrzących prosto na ciebie.",
 jx:"Oskar zrobił kubistycznego psa z kwadratowymi uszami i trójkątnym nosem."},
{id:"art_surrealism",cat:"art",t:"Surrealizm",
 s:"Kierunek w sztuce i literaturze dwudziestego wieku, który badał sny, podświadomość i dziwne, niemożliwe połączenia.",
 l:"Surrealizm narodził się w Paryżu w latach dwudziestych dwudziestego wieku. Jego twórcy chcieli uwolnić wyobraźnię od logiki i pokazać świat snów. Jedni, jak Salvador Dalí czy René Magritte, malowali niemożliwe sceny bardzo realistycznie, na przykład topniejące zegary albo fajkę z podpisem „To nie jest fajka”. Inni, jak Joan Miró, używali zabawnych, niemal abstrakcyjnych form. W mowie potocznej surrealistyczny znaczy dziwny jak sen, na przykład surrealistyczny dzień, w którym nic nie miało sensu.",
 x:"Obraz z pociągiem wyjeżdżającym z kominka to słynny surrealistyczny obraz Magritte’a.",
 f:"Poeta André Breton ogłosił pierwszy „Manifest surrealizmu” w 1924 roku.",
 js:"Sztuka, która wygląda jak dziwny sen.",
 jl:"Surrealiści malowali rzeczy, które można zobaczyć tylko we śnie: zegar topniejący jak ser, rybę na nogach, jabłko unoszące się przed twarzą. Chcieli pokazać, że wyobraźnia może być szalona i zaskakująca.",
 jx:"Na surrealistycznym obrazku Lena narysowała żyrafę na wrotkach na Księżycu."},
{id:"art_abstract",cat:"art",t:"Sztuka abstrakcyjna",
 s:"Sztuka, która nie przedstawia rzeczywistych przedmiotów, lecz posługuje się kształtem, kolorem, linią i fakturą dla nich samych.",
 l:"Obraz abstrakcyjny może składać się wyłącznie z kolorowych kwadratów, plam, pasów albo płynnych form. Niektóre dzieła abstrakcyjne wychodzą od czegoś rzeczywistego i upraszczają to aż do nierozpoznawalności, inne nigdy nie odnosiły się do niczego widzialnego. Artyści wyrażają w ten sposób uczucia, rytm albo idee, a widz może przeżywać je po swojemu. Abstrakcja nie znaczy przypadek: wiele takich dzieł jest starannie zaplanowanych, z równowagą i kolorami dobranymi tak świadomie jak w portrecie.",
 x:"Obraz abstrakcyjny to tylko trzy czerwone pasy, a jednak działa uspokajająco.",
 f:"Muzeum Sztuki w Łodzi, otwarte w 1930 roku dzięki kolekcji zebranej przez awangardową grupę a.r. z Władysławem Strzemińskim, należy do najstarszych muzeów sztuki nowoczesnej na świecie.",
 js:"Sztuka z kształtów i kolorów zamiast prawdziwych rzeczy.",
 jl:"Sztuka abstrakcyjna nie pokazuje domu, psa ani człowieka. Pokazuje kolory, linie i kształty, na przykład zawijasy, kropki albo paski. Najfajniejsze jest to, że każdy może poczuć, patrząc na nią, coś innego.",
 jx:"Mój abstrakcyjny obrazek to same niebieskie zawijasy, bo tak się czuję nad morzem."},
{id:"art_mosaic",cat:"art",t:"Mozaika",
 s:"Obraz lub wzór ułożony z wielu małych kawałków kamienia, szkła lub płytek osadzonych w zaprawie.",
 l:"Twórcy mozaik tną lub zbierają małe elementy, zwane tesserami, i układają je ciasno obok siebie na ścianie, podłodze albo sklepieniu. Z daleka kawałki zlewają się w obraz. Starożytni Rzymianie zdobili podłogi mozaikami ze zwierzętami, bogami i scenami z życia, a artyści bizantyjscy pokrywali ściany kościołów lśniącymi mozaikami ze złoconego szkła, jak w Rawennie we Włoszech. Mozaika jest bardzo trwała, więc wiele z nich przetrwało ponad tysiąc lat.",
 x:"Na dnie basenu jest mozaika z delfinem ułożona z maleńkich niebieskich płytek.",
 f:"Kawałki mozaiki nazywa się tesserami; łacińskie słowo tessera wiąże się z greckim słowem oznaczającym cztery, bo elementy często są mniej więcej kwadratowe i mają cztery rogi.",
 js:"Obrazek ułożony z wielu maleńkich kolorowych kawałków.",
 jl:"Mozaika jest jak układanka, którą się przykleja. Bierzesz malutkie kawałki kolorowego kamienia, szkła albo płytek i kładziesz je obok siebie, aż powstanie obraz. Rzymianie robili mozaiki na podłogach.",
 jx:"Ułożyliśmy mozaikę ze słońcem z kawałków kolorowego papieru."},
{id:"art_watercolour",cat:"art",t:"Akwarela",
 s:"Farba z pigmentu i rozpuszczalnego w wodzie spoiwa, kładziona cienkimi, przejrzystymi warstwami, zwykle na papierze; także obraz wykonany tą farbą.",
 l:"Akwarelę nakłada się z dużą ilością wody, więc kolory są przejrzyste, a spod nich prześwituje biel papieru. Dlatego malarze zwykle zostawiają białe miejsca nietknięte zamiast dodawać białą farbę i pracują od jasnych tonów do ciemnych. Mokre kolory potrafią się w siebie wlewać miękkimi plamami, co ożywia obraz, ale utrudnia kontrolę. Akwarela szybko schnie, łatwo ją nosić i jest lubiana do szkiców w plenerze, rysunków botanicznych i ilustracji książkowych.",
 x:"Namalowała zamglone jezioro akwarelą, pozwalając szarościom rozlewać się po papierze.",
 f:"„Zając” Albrechta Dürera z 1502 roku, namalowany głównie akwarelą i gwaszem, to jeden z najsłynniejszych wizerunków zwierząt w sztuce europejskiej.",
 js:"Farbki, które miesza się z wodą i które są jasne i przezroczyste.",
 jl:"Akwarele to farbki w kostkach albo tubkach. Moczysz pędzelek i kolory robią się jasne i przezroczyste, więc widać przez nie biały papier. Jeśli namalujesz mokre kolory obok siebie, zaczną się ładnie mieszać.",
 jx:"Namalowałem akwarelami zachód słońca i pomarańczowy wpłynął w różowy."},
{id:"art_oil_paint",cat:"art",t:"Farba olejna",
 s:"Farba powstała przez zmieszanie pigmentu z olejem schnącym, najczęściej lnianym.",
 l:"Farba olejna schnie powoli, raczej dniami niż minutami, więc artysta może płynnie łączyć kolory na płótnie i zmieniać zdanie. Można ją kłaść cienkimi, świetlistymi, przejrzystymi warstwami, zwanymi laserunkami, albo grubo, tak że ślady pędzla wystają ponad powierzchnię, czyli impastem. Tradycyjnie maluje się „tłusto na chudym”, dodając więcej oleju w wyższych warstwach, żeby obraz nie pękał. Od piętnastego wieku farba olejna stała się głównym materiałem malarstwa europejskiego.",
 x:"Van Gogh kładł farbę olejną tak grubo, że widać każde pociągnięcie pędzla.",
 f:"Jana van Eycka często błędnie nazywa się wynalazcą malarstwa olejnego; oleje stosowano wcześniej, ale on i inni malarze niderlandzcy piętnastego wieku doprowadzili tę technikę do niezwykłej doskonałości.",
 js:"Gęsta, błyszcząca farba, która bardzo długo schnie.",
 jl:"Wiele słynnych obrazów w muzeach namalowano farbami olejnymi. Są gęste i błyszczące, a schną całymi dniami. Dzięki temu artysta może długo mieszać kolory i poprawiać obraz.",
 jx:"W muzeum widzieliśmy grudki farby olejnej na obrazie ze słonecznikami."},
{id:"art_easel",cat:"art",t:"Sztaluga",
 s:"Stojak, który trzyma obraz lub deskę do rysowania w pionie, gdy artysta pracuje.",
 l:"Sztaluga utrzymuje płótno lub deskę na wygodnej wysokości i pod dobrym kątem, dzięki czemu artysta może stać albo odsunąć się i zobaczyć cały obraz bez zniekształceń. Sztalugi pracowniane są ciężkie i stabilne, a składane sztalugi plenerowe na tyle lekkie, że można je zabrać w teren. Małe sztalugi stołowe służą do pracy przy biurku albo do wystawiania obrazów. Nauczyciele i prelegenci używają sztalug także do trzymania tablic i plansz.",
 x:"Rozstawił sztalugę na plaży i zaczął malować fale.",
 f:"Angielska nazwa sztalugi, easel, pochodzi od niderlandzkiego słowa ezel, czyli osioł, bo stojak dźwiga ciężar jak juczne zwierzę.",
 js:"Stojak, który trzyma obraz, kiedy go malujesz.",
 jl:"Sztaluga to stojak na nóżkach, który trzyma kartkę albo płótno, żebyś nie musiał malować na płasko na stole. Malarze zabierają składane sztalugi na dwór, żeby malować drzewa, góry i morze.",
 jx:"W naszej sali plastycznej stoją trzy sztalugi."},
{id:"art_composition",cat:"art",t:"Kompozycja",
 s:"Sposób rozmieszczenia elementów obrazu tak, by tworzyły zrównoważoną i ciekawą całość.",
 l:"Kompozycja to decyzje o tym, gdzie umieścić przedmioty, jak duże mają być, jak na siebie zachodzą i jak będzie wędrować wzrok widza. Artyści prowadzą oko liniami, grupują kształty, stosują kontrasty światła i koloru oraz puste miejsca, żeby skierować uwagę na to, co najważniejsze. Znaną wskazówką jest zasada trójpodziału: ważne elementy umieszcza się wzdłuż wyobrażonych linii dzielących obraz na trzy części, a nie dokładnie pośrodku. Dobra kompozycja potrafi sprawić, że nawet prosty temat zachwyca.",
 x:"Kompozycja zdjęcia działa, bo ścieżka prowadzi wzrok prosto do latarni morskiej.",
 f:"Wiele aparatów w telefonach może wyświetlić na ekranie siatkę dziewięciu prostokątów, która pomaga stosować zasadę trójpodziału.",
 js:"To, jak ułożone są rzeczy na obrazku.",
 jl:"Kompozycja to decyzja, gdzie wszystko będzie na twoim rysunku. Czy drzewo stoi na środku, czy z boku? Czy kot jest duży, czy mały? Przesuwanie rzeczy może sprawić, że ten sam obrazek będzie nudny albo wspaniały.",
 jx:"Przesunąłem łódkę na bok kartki i kompozycja od razu wyglądała lepiej."},
{id:"art_contrapposto",cat:"art",t:"Kontrapost",
 s:"Swobodna poza stojącej postaci w rzeźbie i malarstwie, z ciężarem ciała na jednej nodze, przez co biodra i ramiona przechylają się w przeciwne strony.",
 l:"W kontrapoście postać opiera ciężar na jednej nodze, a druga jest lekko ugięta w kolanie. Biodra przechylają się wtedy w jedną stronę, a ramiona w drugą i ciało układa się w łagodną linię przypominającą literę S. Taka poza wygląda naturalnie i żywo, w przeciwieństwie do sztywnych postaci stojących prosto na obu stopach. Wypracowali ją rzeźbiarze starożytnej Grecji w piątym wieku przed naszą erą, a artyści renesansu do niej wrócili. Tak samo stoją ludzie czekający na przystanku.",
 x:"Posąg wygląda swobodnie dzięki kontrapostowi – cały ciężar spoczywa na prawej nodze.",
 f:"Marmurowy Dawid Michała Anioła, wykuty w latach 1501–1504, to jeden z najbardziej znanych przykładów kontrapostu.",
 js:"Swobodny sposób stania, z ciężarem ciała na jednej nodze.",
 jl:"Wstań i oprzyj się na jednej nodze, a drugą lekko ugnij w kolanie. Biodra i ramiona się przechylają. Rzeźbiarze w starożytnej Grecji zauważyli, że dzięki temu posąg wygląda na rozluźniony i żywy, a nie sztywny jak żołnierz na warcie.",
 jx:"Pani pokazała nam kontrapost i cała klasa stanęła jak posągi."},
{id:"art_sfumato",cat:"art",t:"Sfumato",
 s:"Technika malarska polegająca na bardzo miękkich, stopniowych przejściach między barwami i tonami, bez ostrych konturów.",
 l:"Sfumato łączy światło z cieniem tak delikatnie, że nie widać, gdzie jedno się kończy, a drugie zaczyna, co daje miękki, zamglony efekt. Malarze osiągali go wieloma bardzo cienkimi, półprzejrzystymi warstwami farby olejnej. Z tą techniką najbardziej kojarzy się Leonardo da Vinci: dzięki niej twarze na jego obrazach mają tajemniczą, żywą miękkość, zwłaszcza wokół oczu i kącików ust. Sfumato różni się od światłocienia, który podkreśla mocny kontrast.",
 x:"Przez sfumato wokół ust trudno orzec, czy ona w ogóle się uśmiecha.",
 f:"Nazwa jest włoska i pochodzi od słowa fumo, czyli dym – kształty zdają się miękko rozpływać, jakby oglądane przez dym.",
 js:"Malowanie tak miękko, że nie ma żadnych ostrych linii.",
 jl:"Sfumato to sposób malowania, w którym kolory łączą się tak delikatnie, że jakby się rozpływały, jak chmurka. Leonardo da Vinci namalował tak Mona Lisę. Dlatego jej twarz wygląda tak łagodnie.",
 jx:"Roztarłem palcem cieniowanie ołówkiem i niebo wyszło jak w sfumato."},
{id:"art_trompe_loeil",cat:"art",t:"Trompe-l’oeil",
 s:"Malarstwo iluzjonistyczne, które oszukuje oko, tak że namalowane rzeczy wydają się prawdziwymi, trójwymiarowymi przedmiotami.",
 l:"Artyści trompe-l’oeil tak zręcznie posługują się perspektywą, światłem i cieniem, że na płaskiej ścianie pojawia się okno, schody albo półka z książkami. Malarze stosowali tę technikę od stuleci, na przykład malując na sufitach udawane kopuły, kolumny i otwarte niebo. Dziś widać ją w sztuce ulicznej, choćby w rysunkach kredą przedstawiających dziury w chodniku, i w muralach, które zdobią zwykłe budynki. Złudzenie działa zwykle najlepiej z jednego, określonego miejsca.",
 x:"Mural trompe-l’oeil sprawił, że ściana wyglądała jak otwarte drzwi do ogrodu.",
 f:"W rzymskim kościele Sant’Ignazio Andrea Pozzo namalował pod koniec siedemnastego wieku kopułę na płaskim stropie i z właściwego miejsca na posadzce wygląda ona jak prawdziwa.",
 js:"Obraz, który oszukuje oczy, że jest prawdziwy.",
 jl:"Niektórzy malarze są tak sprytni, że ich obrazy potrafią cię nabrać. Namalowane okno na ścianie wygląda, jakby dało się je otworzyć, a rysunek kredą na chodniku jak głęboka dziura. Ta sztuczka nazywa się trompe-l’oeil, po francusku: oszukać oko.",
 jx:"Prawie ominąłem narysowaną kredą dziurę w chodniku, a to był tylko trompe-l’oeil."},
{id:"art_pointillism",cat:"art",t:"Puentylizm",
 s:"Technika malarska, w której obraz tworzy się z małych kropek czystego koloru, łączących się w oku widza.",
 l:"Zamiast mieszać farby na palecie, puentyliści kładli obok siebie osobne kropki niezmieszanych barw. Z odległości oko je łączy, więc niebieskie i żółte kropki położone blisko siebie mogą wyglądać jak migotliwa zieleń. Technikę rozwinęli w latach osiemdziesiątych dziewiętnastego wieku Georges Seurat i Paul Signac, zainteresowani naukową wiedzą o kolorze i widzeniu. Ekrany i drukowane obrazki też składają się z maleńkich punktów, co jest podobnym pomysłem.",
 x:"Przyjrzyj się z bliska puentylistycznemu obrazowi, a niebo rozsypie się na tysiące kropek.",
 f:"Georges Seurat pracował około dwóch lat, od 1884 do 1886 roku, nad swoim ogromnym obrazem z kropek „Niedzielne popołudnie na wyspie Grande Jatte”.",
 js:"Malowanie obrazka samymi małymi kropkami.",
 jl:"Puentylizm to malowanie kropkami zamiast pociągnięć pędzla. Z bliska widzisz tylko kolorowe kropki. Kiedy się cofniesz, kropki łączą się w drzewa, ludzi i wodę. Możesz spróbować patyczkiem higienicznym zamoczonym w farbie.",
 jx:"Zrobiliśmy puentylistyczne kwiatki patyczkami higienicznymi i farbą."},
{id:"art_icon",cat:"art",t:"Ikona",
 s:"Święty wizerunek Chrystusa, Matki Bożej lub świętego, malowany na desce, szczególnie w tradycji Kościołów wschodnich.",
 l:"Ikony mają szczególną rolę w Kościele prawosławnym i w Kościołach wschodnich katolickich, gdzie traktuje się je jak okno ku świętości, a nie zwykłą ozdobę. Powstają według tradycyjnych zasad: płaskie, złote tło, spokojne twarze, symboliczne kolory i perspektywa, która jakby wychodzi w stronę widza. Tradycyjnie maluje się je temperą jajową na przygotowanej desce. W informatyce i mowie potocznej ikona oznacza też mały symbol na ekranie albo kogoś powszechnie podziwianego.",
 x:"W cerkwi ściana ikon przed ołtarzem lśniła złotem.",
 f:"W tradycji prawosławnej mówi się często, że ikony się pisze, a nie maluje, bo greckie słowo graphein znaczy zarówno pisać, jak i rysować.",
 js:"Święty obraz namalowany na desce, często ze złotem.",
 jl:"Ikona to wyjątkowy obraz religijny, często przedstawiający Matkę Bożą albo świętego, namalowany na kawałku drewna z błyszczącym złotym tłem. W niektórych kościołach zapala się przed nimi świece. Małe obrazki na ekranie tabletu też nazywają się ikonami.",
 jx:"Babcia ma w pokoju małą ikonę ze złotym tłem."},
{id:"art_collage",cat:"art",t:"Kolaż",
 s:"Praca plastyczna powstała przez naklejanie na podłoże kawałków papieru, zdjęć, tkanin lub innych materiałów.",
 l:"Kolaż łączy w jedną kompozycję różne materiały: wycinki z gazet, bilety, tapetę, sznurek czy liście. Nieoczekiwane zestawienia mogą być zabawne, zaskakujące albo polityczne. Kolaż stał się ważną techniką sztuki nowoczesnej na początku dwudziestego wieku i nadal używa się go w plakatach, okładkach płyt i grafice komputerowej, gdzie obrazy nakłada się na siebie na ekranie. Jest też popularny w szkołach, bo wystarczą nożyczki i klej.",
 x:"Jej kolaż łączy stare mapy, bilety autobusowe i zdjęcia z rodzinnych wakacji.",
 f:"Słowo pochodzi od francuskiego coller, czyli kleić, a Georges Braque i Pablo Picasso zaczęli wklejać papier do swoich obrazów około 1912 roku.",
 js:"Obrazek zrobiony z naklejonych kawałków papieru i innych rzeczy.",
 jl:"Żeby zrobić kolaż, wycinasz kawałki kolorowego papieru, obrazki z gazet, skrawki materiału albo nawet liście i naklejasz je na kartkę. Razem tworzą nowy obraz. Możesz zrobić cokolwiek, od potwora po całe miasto.",
 jx:"Bartek zrobił kolaż z robotem z obrazków z gazet i nakrętek od butelek."},
{id:"art_graffiti",cat:"art",t:"Graffiti",
 s:"Napisy i rysunki na ścianach i innych publicznych powierzchniach, od wydrapanych słów po wielkie malowidła sprayem.",
 l:"Graffiti obejmuje zarówno proste tagi, czyli stylizowane podpisy, jak i rozbudowane, kolorowe malowidła. Współczesne graffiti rozwinęło się w Nowym Jorku w latach siedemdziesiątych dwudziestego wieku, zwłaszcza na wagonach metra, i rozeszło się po świecie razem z kulturą hip-hopu. Malowanie na cudzej własności bez zgody jest w Polsce wykroczeniem lub przestępstwem, ale wiele miast udostępnia legalne ściany i zamawia prace u artystów ulicznych. Wciąż trwają spory o to, gdzie kończy się graffiti, a zaczyna street art.",
 x:"Stary tunel pod torami pokryty jest kolorowym graffiti.",
 f:"Słowo pochodzi od włoskiego graffiare, czyli drapać, a na murach Pompejów zachowały się starożytne graffiti, w tym żarty, pozdrowienia i hasła wyborcze.",
 js:"Napisy albo obrazki namalowane lub wydrapane na ścianach.",
 jl:"Graffiti to napisy i obrazki na ścianach, zrobione farbą w sprayu, flamastrami albo nawet wydrapane. Niektóre są duże i piękne, namalowane za zgodą. Inne powstają tam, gdzie nie wolno, i to może zmartwić właścicieli ściany.",
 jx:"Miasto pozwoliło artystom namalować graffiti ze zwierzętami na murze przy skateparku."},
{id:"art_printmaking",cat:"art",t:"Grafika warsztatowa",
 s:"Tworzenie dzieł przez przenoszenie farby z przygotowanej matrycy, na przykład klocka drewna lub metalowej płyty, na papier.",
 l:"W grafice warsztatowej artysta przygotowuje matrycę, a potem odbija z niej prace, często wiele razy. W drzeworycie i linorycie część klocka się wycina, a farba zostaje na wypukłych miejscach. W akwaforcie i miedziorycie linie ryje się albo wytrawia kwasem w metalowej płycie, a farbę wciera w te rowki. W serigrafii farbę przeciska się przez gęstą siatkę. Każda odbitka z tej samej matrycy jest oryginałem, a artyści często je numerują, na przykład pięć na pięćdziesiąt.",
 x:"Na warsztatach wycięliśmy w linoleum jeża i odbiliśmy go na kartkach.",
 f:"Albrecht Dürer wykonał w 1515 roku słynny drzeworyt z nosorożcem, choć nigdy nie widział tego zwierzęcia – pracował na podstawie opisu i szkicu przysłanych z Lizbony.",
 js:"Robienie obrazków przez odbijanie na papierze kształtu pokrytego farbą.",
 jl:"Grafika warsztatowa przypomina bardzo wymyślną pieczątkę. Wycinasz obrazek w klocku drewna albo miękkim linoleum, wałkiem nakładasz farbę i przyciskasz papier. Ten sam obrazek możesz odbić wiele razy.",
 jx:"Wycięliśmy w ziemniaku gwiazdkę i odbiliśmy gwiazdki na papierze do pakowania prezentów."},
{id:"art_restoration",cat:"art",t:"Konserwacja dzieł sztuki",
 s:"Staranne czyszczenie, naprawianie i zabezpieczanie uszkodzonych dzieł sztuki.",
 l:"Konserwatorzy, zanim czegokolwiek dotkną, badają materiały i stan dzieła. Mogą usunąć brud i zżółkły werniks, umocnić łuszczącą się farbę, naprawić rozdarcia czy uzupełnić drobne ubytki. Współczesna zasada mówi, że ingerencja ma być jak najmniejsza, dobrze udokumentowana i w miarę możliwości odwracalna, tak by następni specjaliści mogli ją cofnąć lepszymi metodami. Pomagają naukowcy z promieniami rentgenowskimi, podczerwienią i analizą farb, które czasem odsłaniają pod powierzchnią wcześniejsze szkice.",
 x:"Po konserwacji obrazu na niebie znów pojawił się intensywny błękit.",
 f:"Wielkie czyszczenie fresków Michała Anioła w Kaplicy Sykstyńskiej trwało od 1980 do 1994 roku i odsłoniło kolory znacznie jaśniejsze, niż wszyscy byli przyzwyczajeni.",
 js:"Ostrożne czyszczenie i naprawianie starych dzieł sztuki.",
 jl:"Bardzo stare obrazy mogą się zabrudzić, popękać albo wyblaknąć. Specjaliści, zwani konserwatorami, czyszczą je malutkimi pędzelkami i delikatnymi płynami oraz ostrożnie naprawiają. Starają się nigdy nie zmieniać tego, co stworzył artysta.",
 jx:"W muzeum patrzyliśmy, jak konserwatorka czyści obraz wacikiem."},
{id:"art_negative_space",cat:"art",t:"Przestrzeń negatywna",
 s:"Pusta przestrzeń wokół głównych motywów obrazu lub rzeźby i między nimi.",
 l:"Przestrzeń negatywna to wszystko, co nie jest głównym motywem: niebo wokół drzewa, szpara między filiżanką a jej uchem. Artyści zwracają na nią uwagę, bo puste kształty są dla kompozycji tak samo ważne jak przedmioty. Rysowanie pustych przestrzeni zamiast samego przedmiotu to klasyczne ćwiczenie, które pomaga rysować dokładniej. Projektanci sprytnie wykorzystują ją w logo, gdzie puste miejsce tworzy drugi, ukryty obrazek.",
 x:"Spójrz na przestrzeń negatywną między dwiema twarzami w logo, a zobaczysz wazon.",
 f:"Słynny obrazek, na którym widać wazon albo dwie twarze, nazywa się wazą Rubina od duńskiego psychologa Edgara Rubina, który opisał go około 1915 roku.",
 js:"Pusta przestrzeń wokół rzeczy na obrazku.",
 jl:"Kiedy rysujesz krzesło, między jego nogami są puste miejsca. Te puste kształty to przestrzeń negatywna. Artyści dokładnie się im przyglądają, bo pomagają, żeby rysunek wyglądał dobrze.",
 jx:"Zamiast rysować roślinę, pokolorowaliśmy przestrzeń negatywną wokół jej liści."},
{id:"art_pl_mloda_polska",cat:"art",only:1,c:"Polska",t:"Młoda Polska",
 s:"Epoka w polskiej sztuce i literaturze na przełomie dziewiętnastego i dwudziestego wieku, mniej więcej od 1890 do 1918 roku.",
 l:"Artyści Młodej Polski szukali nowego języka sztuki: sięgali po symbole, nastrój, baśnie i ludowość, a zarazem żywo interesowali się sztuką Paryża i Wiednia. Ważnym ośrodkiem był Kraków. Do najważniejszych malarzy należeli Stanisław Wyspiański, Jacek Malczewski, Józef Mehoffer, Leon Wyczółkowski i Olga Boznańska, a w literaturze między innymi Kazimierz Przerwa-Tetmajer i Stanisław Przybyszewski. Często pojawiają się motywy natury, polskiej historii i pragnienia wolności kraju podzielonego przez zaborców.",
 x:"Na lekcji oglądaliśmy obrazy Malczewskiego, jednego z najważniejszych malarzy Młodej Polski.",
 f:"Stanisław Wyspiański zaprojektował witraże w kościele Franciszkanów w Krakowie, w tym słynny witraż „Bóg Ojciec – Stań się!”.",
 js:"Czas w polskiej sztuce około sto dwadzieścia lat temu, pełen baśni, natury i kolorów.",
 jl:"Ponad sto lat temu polscy artyści malowali kwiaty, łąki, baśniowe postacie i sceny z historii. Polska nie była wtedy wolnym krajem, a sztuka pomagała ludziom marzyć o wolności. Ten czas nazywamy Młodą Polską.",
 jx:"W Krakowie oglądaliśmy kolorowe witraże Wyspiańskiego z czasów Młodej Polski."},
{id:"art_pl_wycinanka",cat:"art",only:1,c:"Polska",t:"Wycinanka ludowa",
 s:"Tradycyjna polska ozdoba z kolorowego papieru, wycinana nożyczkami w symetryczne wzory.",
 l:"Wycinankami dawniej zdobiono wiejskie chaty, zwłaszcza ściany i belki, na przykład przed świętami. Każdy region miał własny styl. Wycinanki łowickie są wielobarwne, warstwowe i pełne kwiatów, ptaków oraz scen z życia wsi. Kurpiowskie są zwykle jednobarwne i symetryczne, z motywami takimi jak drzewko życia czy leluja. Dziś wycinanka jest jednym z symboli polskiej sztuki ludowej, a jej wzory pojawiają się na pocztówkach, tkaninach i w nowoczesnym designie.",
 x:"Na jarmarku kupiliśmy łowicką wycinankę z kogutami i kwiatami.",
 f:"Na Kurpiach wycinanki tradycyjnie wycinano nożycami do strzyżenia owiec.",
 js:"Kolorowy wzór wycięty nożyczkami z papieru, tradycyjna polska ozdoba.",
 jl:"Dawno temu na wsiach ludzie zdobili domy wzorami z papieru. Składali kolorową kartkę i wycinali nożyczkami kwiaty, ptaki i drzewka. Po rozłożeniu wzór był taki sam z obu stron. To wycinanka i możesz ją zrobić także w szkole.",
 jx:"Złożyłam zieloną kartkę na pół i wycięłam wycinankę w kształcie drzewka."},
{id:"art_pl_pisanka",cat:"art",only:1,c:"Polska",t:"Pisanka",
 s:"Wielkanocne jajko ozdobione wzorami, tradycyjnie rysowanymi roztopionym woskiem przed farbowaniem.",
 l:"Tradycyjną pisankę robi się techniką batikową: na jajku rysuje się wzory gorącym woskiem, na przykład szpilką lub specjalnym rysikiem, a potem zanurza je w barwniku. Pod woskiem skorupka zostaje jasna, a po zdjęciu wosku widać wzór. Jednobarwne jajka bez wzorów to kraszanki, barwione dawniej naturalnie, na przykład w łupinach cebuli. Są też drapanki, na których wzór wydrapuje się ostrym narzędziem na już ufarbowanej skorupce. Pisanki należą do najważniejszych symboli polskiej Wielkanocy.",
 x:"W Wielką Sobotę babcia uczyła nas robić pisanki z woskiem.",
 f:"Nazwa pochodzi od czasownika pisać, bo wzory „pisze się” woskiem, a najstarszą pisankę na ziemiach polskich znaleziono w Opolu – pochodzi z dziesiątego wieku.",
 js:"Kolorowe jajko wielkanocne ozdobione wzorkami.",
 jl:"Przed Wielkanocą robimy pisanki. Na jajku rysuje się wzorki ciepłym woskiem, a potem wkłada je do farbki. Tam, gdzie był wosk, zostaje jasny wzór. Jajka w jednym kolorze, na przykład z łupin cebuli, to kraszanki.",
 jx:"Moja pisanka ma niebieskie kwiatki i żółte kropki."},
{id:"art_pl_szkola_plakatu",cat:"art",only:1,c:"Polska",t:"Polska Szkoła Plakatu",
 s:"Nazwa nurtu w polskiej grafice użytkowej lat pięćdziesiątych i sześćdziesiątych dwudziestego wieku, słynącego z artystycznych plakatów.",
 l:"Plakaty filmowe, teatralne i cyrkowe tworzone w Polsce w tym czasie były małymi dziełami sztuki. Zamiast pokazywać zdjęcia aktorów, artyści tworzyli własną metaforę utworu: zabawną, poetycką albo niepokojącą, często z odręcznym liternictwem. Do najważniejszych twórców należeli Henryk Tomaszewski, Jan Lenica, Roman Cieślewicz, Waldemar Świerzy i Franciszek Starowieyski. Polska Szkoła Plakatu zyskała uznanie na całym świecie i do dziś inspiruje grafików.",
 x:"Plakat do filmu w stylu Polskiej Szkoły Plakatu nie pokazywał aktorów, tylko jeden dziwny, piękny symbol.",
 f:"Muzeum Plakatu w Wilanowie otwarto w 1968 roku i uważa się je za jedno z pierwszych muzeów plakatu na świecie, a od 1966 roku w Warszawie odbywa się Międzynarodowe Biennale Plakatu.",
 js:"Słynne polskie plakaty sprzed lat, które były prawdziwymi dziełami sztuki.",
 jl:"Dawniej w Polsce plakaty do filmów, teatru i cyrku malowali artyści. Zamiast zdjęć aktorów wymyślali zabawne albo zagadkowe obrazki. Były tak piękne, że ludzie na całym świecie je podziwiali i dziś wiszą w muzeach.",
 jx:"W Muzeum Plakatu oglądaliśmy kolorowy plakat cyrkowy z lwem w kapeluszu."},
/* ---------- MEDYCYNA (+6) ---------- */
{id:"m_mri",cat:"med",t:"Rezonans magnetyczny",
 s:"Badanie obrazowe, które za pomocą silnego magnesu i fal radiowych tworzy dokładne obrazy wnętrza ciała.",
 l:"Rezonans magnetyczny, w skrócie MR lub MRI, wykonuje się, gdy pacjent leży na stole wsuwanym do aparatu w kształcie tunelu. Urządzenie wytwarza silne pole magnetyczne i wysyła impulsy fal radiowych. Atomy wodoru w tkankach na nie reagują, a komputer zamienia sygnały w szczegółowe obrazy, szczególnie przydatne przy badaniu mózgu, kręgosłupa, stawów i tkanek miękkich. Badanie nie boli, ale jest głośne, więc pacjent dostaje ochronniki słuchu. Ze względu na magnes trzeba wcześniej sprawdzić metalowe przedmioty i niektóre implanty.",
 x:"Lekarz skierował ją na rezonans magnetyczny, żeby obejrzeć więzadła w kolanie.",
 f:"Rezonans nie wykorzystuje promieniowania rentgenowskiego ani innego jonizującego; Paul Lauterbur i Peter Mansfield otrzymali za prace nad tą metodą Nagrodę Nobla w dziedzinie fizjologii lub medycyny w 2003 roku.",
 js:"Duża maszyna, która magnesem robi zdjęcia wnętrza ciała.",
 jl:"Aparat do rezonansu wygląda jak wielki tunel z mocnym magnesem w środku. Leżysz bardzo spokojnie na łóżku, które do niego wjeżdża. Maszyna głośno stuka, ale nic nie boli. Lekarz dostaje wyraźne zdjęcia twojego wnętrza, na przykład mózgu albo kolana.",
 jx:"Amir miał rezonans i słuchał muzyki w słuchawkach, kiedy maszyna buczała."},
{id:"m_x_ray",cat:"med",t:"Zdjęcie rentgenowskie",
 s:"Obraz wnętrza ciała wykonany promieniowaniem, które przechodzi przez tkanki miękkie, ale zatrzymuje się na kościach.",
 l:"Na zdjęciu rentgenowskim, nazywanym potocznie prześwietleniem albo RTG, gęste struktury, takie jak kości i zęby, pochłaniają więcej promieniowania i są białe, a tkanki miękkie i powietrze mają odcienie szarości i czerni. Badanie jest szybkie i często stosowane przy złamaniach, zapaleniu płuc czy problemach z zębami. Dawka przy jednym zwykłym zdjęciu jest niewielka, ale personel i tak ogranicza narażenie, dlatego wychodzi za osłonę i pyta pacjentki o ciążę. Tomografia komputerowa wykorzystuje promienie rentgenowskie z wielu stron, by tworzyć obrazy przekrojów.",
 x:"Zdjęcie rentgenowskie pokazało małe pęknięcie kości nadgarstka.",
 f:"Wilhelm Conrad Röntgen odkrył promienie X w 1895 roku, a jedno z jego pierwszych zdjęć pokazywało kości dłoni jego żony i obrączkę na palcu.",
 js:"Specjalne zdjęcie, na którym widać kości.",
 jl:"Kiedy ktoś mógł złamać kość, lekarz robi zdjęcie rentgenowskie. Widać na nim kości na biało, bo specjalne promienie przechodzą przez skórę, ale nie przez kość. Trwa to chwilkę i nic nie boli.",
 jx:"Po upadku z roweru zdjęcie rentgenowskie pokazało, że ręka nie jest złamana."},
{id:"m_insulin",cat:"med",t:"Insulina",
 s:"Hormon wytwarzany przez trzustkę, który pomaga komórkom ciała pobierać cukier z krwi.",
 l:"Po jedzeniu cukier w postaci glukozy trafia do krwi, a trzustka wydziela insulinę, która działa jak klucz otwierający komórkom dostęp do glukozy jako źródła energii. W cukrzycy typu pierwszego organizm wytwarza mało insuliny albo wcale, więc chorzy muszą ją przyjmować codziennie, we wstrzyknięciach lub przez małą pompę. W cukrzycy typu drugiego organizm słabo reaguje na insulinę lub wytwarza jej za mało. Leczenie każdej osoby ustala indywidualnie lekarz i zespół diabetologiczny.",
 x:"Pompa insulinowa pomaga jej utrzymać stały poziom cukru podczas meczów piłki nożnej.",
 f:"Insulinę odkryli w Toronto w 1921 roku Frederick Banting i Charles Best we współpracy z innymi badaczami, a pierwszego pacjenta leczono nią w styczniu 1922 roku.",
 js:"Coś, co wytwarza twoje ciało, żeby móc używać cukru jako energii.",
 jl:"Twoje ciało zamienia jedzenie w rodzaj cukru, który daje energię. Insulina jest jak klucz, który otwiera drzwi komórek, żeby cukier mógł do nich wejść. Niektóre dzieci mają cukrzycę i ich ciało potrzebuje pomocy z insuliną, często z małej pompy albo zastrzyków.",
 jx:"Moja koleżanka Ola sprawdza cukier przed WF-em i w razie potrzeby bierze insulinę."},
{id:"m_microbiome",cat:"med",t:"Mikrobiom",
 s:"Ogromna społeczność bakterii, grzybów i innych drobnoustrojów żyjących w ciele człowieka i na nim.",
 l:"Biliony drobnoustrojów żyją na naszej skórze, w jamie ustnej, a zwłaszcza w jelitach. Większość jest nieszkodliwa albo pożyteczna: bakterie jelitowe pomagają rozkładać błonnik, wytwarzają niektóre witaminy i uczą układ odpornościowy. Mikrobiom zmienia się pod wpływem diety, chorób, leków takich jak antybiotyki i otoczenia. Naukowcy intensywnie badają jego związki z wieloma chorobami, ale wiele pozostaje niejasne, więc do śmiałych obietnic z reklam suplementów warto podchodzić ostrożnie.",
 x:"Warzywa i strączki pełne błonnika są pożywką dla zdrowego mikrobiomu jelit.",
 f:"Dawniej twierdzono, że bakterii w ciele jest dziesięć razy więcej niż ludzkich komórek, ale badanie opublikowane w 2016 roku oszacowało, że jest ich mniej więcej tyle samo.",
 js:"Wszystkie maleńkie żyjątka, na przykład pożyteczne bakterie, które mieszkają w twoim ciele i na nim.",
 jl:"W twoim ciele mieszkają miliardy maleńkich żyjątek, za małych, żeby je zobaczyć. Wiele z nich żyje w brzuchu i pomaga trawić jedzenie. Większość to przyjaźni pomocnicy, a owoce i warzywa sprawiają, że dobrze im się żyje.",
 jx:"Na lekcji dowiedzieliśmy się, że bakterie w brzuchu pomagają nam trawić obiad."},
{id:"m_hand_hygiene",cat:"med",t:"Higiena rąk",
 s:"Mycie rąk wodą z mydłem lub dezynfekcja preparatem na bazie alkoholu, by usunąć zarazki i zapobiec zakażeniom.",
 l:"Rękami przez cały dzień dotykamy twarzy, jedzenia i innych ludzi, więc łatwo przenoszą wirusy i bakterie. Mycie mydłem pod bieżącą wodą przez około dwadzieścia sekund, z pocieraniem wnętrza dłoni, ich grzbietów, przestrzeni między palcami i miejsc pod paznokciami, usuwa wiele zarazków. Gdy nie ma mydła, płyny na bazie alkoholu działają na wiele drobnoustrojów, ale gorzej na bardzo brudne ręce. W szpitalach higiena rąk przed kontaktem z każdym pacjentem i po nim to jeden z najskuteczniejszych sposobów zapobiegania zakażeniom.",
 x:"Pielęgniarka dezynfekowała ręce przed wizytą u każdego pacjenta i po niej.",
 f:"W 1847 roku w Wiedniu lekarz Ignác Semmelweis wykazał, że gdy lekarze myli ręce w roztworze chloru, zakażeń wśród kobiet po porodzie w jego klinice było znacznie mniej, ale wielu kolegów odrzuciło jego pomysł.",
 js:"Dokładne mycie rąk, żeby pozbyć się zarazków.",
 jl:"Zarazki są za małe, żeby je zobaczyć, ale trafiają na ręce, kiedy czegoś dotykamy. Mycie rąk wodą z mydłem tak długo, jak trwa dwukrotne zaśpiewanie „Sto lat”, usuwa większość z nich. Dzięki temu ty i inni rzadziej chorujecie.",
 jx:"Przed obiadem cała klasa myje ręce i dwa razy śpiewa „Sto lat”."},
{id:"m_pl_nfz",cat:"med",only:1,c:"Polska",t:"NFZ",
 s:"Narodowy Fundusz Zdrowia, instytucja, która w Polsce finansuje ze składek publiczną opiekę zdrowotną.",
 l:"NFZ nie leczy sam, lecz podpisuje umowy z przychodniami, szpitalami, gabinetami i aptekami i płaci im za świadczenia dla pacjentów. Pieniądze pochodzą głównie ze składek na ubezpieczenie zdrowotne. Osoby ubezpieczone i członkowie ich rodzin mogą korzystać z leczenia „na NFZ”, czyli bez płacenia za wizytę, choć na niektóre świadczenia czeka się w kolejce. Dzieci i młodzież do ukończenia osiemnastu lat mają prawo do bezpłatnej opieki zdrowotnej niezależnie od ubezpieczenia rodziców.",
 x:"Na wizytę u ortopedy na NFZ trzeba mieć skierowanie od lekarza rodzinnego.",
 f:"Narodowy Fundusz Zdrowia działa od 2003 roku, kiedy zastąpił dawne kasy chorych; ma centralę w Warszawie i szesnaście oddziałów wojewódzkich.",
 js:"Polska instytucja, która płaci lekarzom i szpitalom za leczenie ludzi.",
 jl:"Kiedy idziesz do lekarza w przychodni, twoi rodzice zwykle nie płacą za wizytę. Za lekarza płaci NFZ, z pieniędzy, które dorośli co miesiąc odkładają na zdrowie wszystkich. Dzieci w Polsce mają prawo do bezpłatnego leczenia.",
 jx:"Pani w rejestracji zapytała, czy przychodzimy na NFZ."},
/* ---------- PRAWO (+6) ---------- */
{id:"l_faulty_goods",cat:"law",c:"Polska",t:"Reklamacja towaru",
 s:"Zgłoszenie sprzedawcy, że kupiona rzecz jest wadliwa lub niezgodna z umową, wraz z żądaniem naprawy, wymiany albo zwrotu pieniędzy.",
 l:"Od 2023 roku prawa konsumenta przy wadliwym towarze opisuje ustawa o prawach konsumenta jako odpowiedzialność za brak zgodności towaru z umową. Sprzedawca odpowiada za niezgodność, która ujawni się w ciągu dwóch lat od wydania rzeczy. Konsument najpierw może żądać naprawy albo wymiany, a gdy to niemożliwe lub się nie uda, obniżenia ceny lub odstąpienia od umowy i zwrotu pieniędzy. Na reklamację sprzedawca powinien odpowiedzieć w ciągu czternastu dni; brak odpowiedzi oznacza jej uznanie.",
 x:"Czajnik zepsuł się po tygodniu, więc złożyła reklamację i dostała nowy.",
 f:"Do reklamacji nie jest konieczny paragon: zakup można udowodnić także na przykład potwierdzeniem płatności kartą albo wyciągiem z konta.",
 js:"Oddanie do sklepu zepsutej rzeczy, żeby ją naprawili, wymienili albo oddali pieniądze.",
 jl:"Jeśli kupisz zabawkę, a ona od razu się psuje, bo była źle zrobiona, to nie fair. Prawo mówi, że sklep musi pomóc: naprawić ją, dać nową albo oddać pieniądze. To się nazywa reklamacja. Warto zachować paragon.",
 jx:"Moje nowe słuchawki przestały działać, więc mama zaniosła je na reklamację i dostaliśmy nowe."},
{id:"l_notary",cat:"law",c:"Polska",t:"Notariusz",
 s:"Prawnik, który jako osoba zaufania publicznego sporządza dokumenty urzędowe, zwane aktami notarialnymi, i poświadcza podpisy.",
 l:"W Polsce notariusz ma szeroką rolę. Sporządza akty notarialne, które mają moc dokumentów urzędowych, poświadcza podpisy, odpisy i daty, przygotowuje testamenty i umowy spółek. Niektóre czynności wymagają formy aktu notarialnego pod rygorem nieważności, na przykład umowa przeniesienia własności nieruchomości. Notariusz powinien być bezstronny i czuwać nad zabezpieczeniem praw i interesów stron. Jego wynagrodzenie ma ustawowe górne granice, zwane taksą notarialną.",
 x:"Umowę sprzedaży mieszkania podpisali w kancelarii notarialnej.",
 f:"Zawód notariusza reguluje w Polsce ustawa Prawo o notariacie z 1991 roku.",
 js:"Prawnik, który spisuje i pieczętuje bardzo ważne dokumenty.",
 jl:"Notariusz to prawnik, który pomaga ludziom przy bardzo ważnych sprawach, na przykład kupnie mieszkania. Spisuje umowę, czyta ją wszystkim na głos, sprawdza, kto podpisuje, i przystawia oficjalną pieczęć.",
 jx:"Dziadkowie poszli do notariusza, żeby podpisać umowę kupna domku na wsi."},
{id:"l_statute",cat:"law",c:"Polska",t:"Ustawa",
 s:"Akt prawny uchwalany przez Sejm i Senat, najważniejszy po Konstytucji rodzaj prawa w Polsce.",
 l:"Projekt ustawy może zgłosić grupa posłów, Senat, Prezydent, Rada Ministrów albo grupa obywateli. Sejm rozpatruje go w trzech czytaniach, potem trafia do Senatu, który może przyjąć go bez zmian, wprowadzić poprawki albo go odrzucić. Następnie ustawę podpisuje Prezydent; może też skierować ją do Trybunału Konstytucyjnego lub zawetować, a Sejm może weto odrzucić większością trzech piątych głosów. Ustawa wchodzi w życie po ogłoszeniu w Dzienniku Ustaw.",
 x:"Nowa ustawa wejdzie w życie czternaście dni od ogłoszenia.",
 f:"Według Konstytucji projekt ustawy może złożyć w Sejmie grupa co najmniej stu tysięcy obywateli mających prawo wybierania posłów.",
 js:"Prawo uchwalone przez Sejm i Senat, którego muszą przestrzegać wszyscy.",
 jl:"W Polsce najważniejsze prawa uchwalają posłowie w Sejmie i senatorowie w Senacie. Najpierw dyskutują i głosują, a potem prezydent podpisuje taką ustawę. Od tej chwili wszyscy w kraju muszą się do niej stosować.",
 jx:"Na lekcji WOS-u dowiedzieliśmy się, jak powstaje ustawa."},
{id:"l_compensation",cat:"law",c:"Polska",t:"Odszkodowanie",
 s:"Pieniądze, które sprawca szkody musi zapłacić poszkodowanemu, by naprawić wyrządzoną stratę.",
 l:"Odszkodowanie ma wyrównać szkodę majątkową: koszty naprawy, utracone zarobki, wydatki na leczenie czy zniszczone rzeczy. Obejmuje zarówno faktyczną stratę, jak i korzyści, które poszkodowany mógłby osiągnąć, gdyby szkody nie wyrządzono. Poszkodowany musi wykazać szkodę i jej związek z działaniem drugiej strony. Za krzywdę niemajątkową, na przykład ból i cierpienie, sąd może przyznać zadośćuczynienie, które jest odrębnym roszczeniem. Odszkodowanie różni się od grzywny, którą płaci się państwu jako karę.",
 x:"Firma budowlana wypłaciła sąsiadom odszkodowanie za zalane mieszkanie.",
 f:"Podstawowa zasada polskiego prawa cywilnego brzmi w Kodeksie cywilnym: kto z winy swej wyrządził drugiemu szkodę, obowiązany jest do jej naprawienia.",
 js:"Pieniądze, które ktoś musi zapłacić, bo coś zepsuł lub komuś zaszkodził.",
 jl:"Jeśli ktoś przez nieuwagę zniszczy twoją rzecz, uczciwie jest, żeby zapłacił za naprawę. W prawie pieniądze, które wynagradzają taką stratę, to odszkodowanie. O tym, ile wynosi, może zdecydować sąd.",
 jx:"Piłka wybiła nam szybę i sąsiad zapłacił za nową."},
{id:"l_terms_conditions",cat:"law",c:"Polska",t:"Regulamin",
 s:"Spisane zasady korzystania z usługi, sklepu albo miejsca, które akceptuje się, zawierając umowę.",
 l:"Regulamin sklepu internetowego, aplikacji czy siłowni opisuje między innymi ceny, płatności, dostawę, rezygnację, przetwarzanie danych i składanie reklamacji. Zaznaczając okienko lub korzystając z usługi, zwykle go akceptujemy, nawet jeśli go nie przeczytaliśmy. Postanowienia, które rażąco naruszają interesy konsumenta i nie zostały z nim indywidualnie uzgodnione, to klauzule niedozwolone, nazywane abuzywnymi; nie wiążą one konsumenta. Nadzór nad tym sprawuje między innymi Urząd Ochrony Konkurencji i Konsumentów.",
 x:"Zanim zapisał się na siłownię, przeczytał w regulaminie, jak można zrezygnować.",
 f:"Urząd Ochrony Konkurencji i Konsumentów prowadził rejestr klauzul niedozwolonych, w którym znalazły się tysiące przykładów nieuczciwych postanowień uznanych przez sąd.",
 js:"Zasady, na które się zgadzasz, gdy coś kupujesz albo zapisujesz się do aplikacji.",
 jl:"Kiedy dorośli zakładają konto w aplikacji albo kupują coś w internecie, często jest długa strona z zasadami, czyli regulamin. Mówi, co wolno, a czego nie. Regulamin ma też basen czy biblioteka. Warto przeczytać go razem z dorosłym.",
 jx:"Na basenie wisi regulamin: nie wolno biegać przy wodzie."},
{id:"l_pl_pesel",cat:"law",only:1,c:"Polska",t:"PESEL",
 s:"Jedenastocyfrowy numer identyfikacyjny nadawany w Polsce każdej osobie wpisanej do rejestru mieszkańców.",
 l:"Numer PESEL nadaje się zwykle krótko po urodzeniu. Służy do identyfikacji w urzędach, szkołach, u lekarza, w banku czy przy podatkach. Pierwsze sześć cyfr zawiera datę urodzenia, kolejne cyfry to numer porządkowy, przedostatnia cyfra wskazuje płeć, a ostatnia jest cyfrą kontrolną, która pozwala wykryć pomyłki przy przepisywaniu. Ponieważ numer pozwala zidentyfikować osobę, należy go chronić i nie podawać bez potrzeby. W aplikacji mObywatel można zastrzec swój PESEL, co utrudnia oszustom zaciągnięcie kredytu na cudze dane.",
 x:"Przy zapisie do przychodni poproszono o numer PESEL dziecka.",
 f:"Skrót PESEL pochodzi od nazwy Powszechny Elektroniczny System Ewidencji Ludności, utworzonego w latach siedemdziesiątych dwudziestego wieku.",
 js:"Twój specjalny numer z jedenastu cyfr, który masz od urodzenia.",
 jl:"Każde dziecko w Polsce dostaje zaraz po urodzeniu specjalny numer z jedenastu cyfr, czyli PESEL. Ukryta jest w nim data urodzenia. Lekarz albo szkoła używają go, żeby nie pomylić osób. To numer, którego nie podaje się obcym.",
 jx:"Pani w szkole wpisała mój PESEL do dziennika."},
/* ---------- JĘZYK OGÓLNY (+6) ---------- */
{id:"g_jargon",cat:"gen",t:"Żargon",
 s:"Specjalne słownictwo jakiejś grupy lub zawodu, często niezrozumiałe dla osób z zewnątrz.",
 l:"Każda dziedzina ma swój żargon: lekarze mówią o rokowaniu, gracze o respawnie, a pracownicy biur o deadline’ach i call’ach. Żargon bywa przydatny, bo pozwala specjalistom mówić szybko i precyzyjnie. Kiedy jednak używa się go w rozmowie z osobami, które go nie znają, może je zagubić, wykluczyć albo sprawić, że proste rzeczy brzmią na skomplikowane. Dobrzy mówcy zauważają własny żargon i tłumaczą go albo zastępują prostymi słowami.",
 x:"Wykład inżyniera był tak pełen żargonu, że połowa słuchaczy się pogubiła.",
 f:"Słowo przyszło do polszczyzny z francuskiego, a w średniowiecznej francuszczyźnie jargon oznaczało świergot ptaków.",
 js:"Specjalne słowa, które rozumieją tylko ludzie z danego zawodu albo hobby.",
 jl:"Ludzie, którzy mają ten sam zawód albo hobby, często używają specjalnych słów. Mają je lekarze, piłkarze i gracze komputerowi. Takie słowa to żargon. Jeśli ich nie znasz, brzmi to jak tajny język.",
 jx:"Mój brat używa tyle żargonu z gier, że w ogóle go nie rozumiem."},
{id:"g_etymology",cat:"gen",t:"Etymologia",
 s:"Pochodzenie i historia wyrazu, a także nauka badająca, skąd wzięły się formy i znaczenia słów.",
 l:"Etymologia śledzi drogę słowa przez dawne formy i inne języki. Pokazuje na przykład, że wiele polskich wyrazów ma wspólne korzenie z innymi językami słowiańskimi, a inne przyszły z łaciny, niemieckiego, francuskiego czy tureckiego, i że znaczenia zmieniają się z czasem. Etymolodzy opierają się na dawnych tekstach i porównaniu języków. Popularne opowieści o pochodzeniu słów często są nieprawdziwe; takie wymyślone wyjaśnienia nazywa się etymologią ludową.",
 x:"Etymologia słowa „szkoła” prowadzi przez łacinę aż do greki.",
 f:"Samo słowo etymologia pochodzi z greki: etymon oznacza prawdziwe znaczenie wyrazu, a logos – słowo, naukę.",
 js:"Skąd pochodzi dane słowo i jak powstało.",
 jl:"Słowa mają swoje historie. Niektóre powstały dawno temu w innych językach i zmieniały się z czasem. Etymologia to odkrywanie, skąd słowo pochodzi. Na przykład dinozaur pochodzi od greckich słów znaczących straszny jaszczur.",
 jx:"Sprawdziliśmy etymologię słowa „telefon”: pochodzi od greckich słów oznaczających daleko i głos."},
{id:"g_tongue_twister",cat:"gen",t:"Łamaniec językowy",
 s:"Zdanie trudne do szybkiego i poprawnego wypowiedzenia z powodu powtarzających się podobnych głosek.",
 l:"Łamańce językowe, nazywane też łamigłówkami językowymi, skupiają głoski, które łatwo pomylić, na przykład sz, cz, ś i ć, więc przy szybkim mówieniu język się plącze. To popularna zabawa, ale aktorzy, śpiewacy, prezenterzy i logopedzi używają ich także do rozgrzewki i ćwiczenia wyraźnej wymowy. Każdy język ma swoje słynne łamańce i zwykle nie da się ich przetłumaczyć, bo trudność tkwi w brzmieniu, a nie w znaczeniu. Polszczyzna, bogata w zbitki spółgłosek, ma ich wyjątkowo dużo.",
 x:"„Stół z powyłamywanymi nogami” to łamaniec, który ćwiczy niejedno dziecko.",
 f:"Słynne zdanie „W Szczebrzeszynie chrząszcz brzmi w trzcinie” pochodzi z wiersza Jana Brzechwy „Chrząszcz”.",
 js:"Śmieszne zdanie, które bardzo trudno szybko powiedzieć.",
 jl:"Łamaniec językowy to zdanie pełne podobnych dźwięków, na przykład Król Karol kupił królowej Karolinie korale koloru koralowego. Spróbuj powiedzieć je szybko pięć razy! Język się plącze. To świetna zabawa, a przy okazji uczy wyraźnego mówienia.",
 jx:"Spróbuj szybko powiedzieć trzy razy pod rząd: „Czarna krowa w kropki bordo gryzła trawę, kręcąc mordą”!"},
{id:"g_loanword",cat:"gen",t:"Zapożyczenie",
 s:"Wyraz przejęty z jednego języka do drugiego, często z niewielkimi zmianami.",
 l:"Języki stale pożyczają od siebie słowa dzięki handlowi, podróżom, nauce, kuchni i technice. Polszczyzna ma zapożyczenia z wielu języków: z łaciny przyszła szkoła, z niemieckiego ratusz i dach, z francuskiego bagaż, z włoskiego pomidor, z tureckiego kawa i dywan, a z angielskiego weekend i komputer. Z czasem zapożyczenia dostosowują pisownię i odmianę do nowego języka, jak w słowie szofer z francuskiego chauffeur. Niektórzy nie lubią zapożyczeń, ale to jeden z najzwyklejszych sposobów rozwoju języka.",
 x:"„Weekend” to zapożyczenie z angielskiego, które na dobre zadomowiło się w polszczyźnie.",
 f:"Słowo robot weszło do polszczyzny i wielu innych języków z czeskiego, dzięki sztuce Karla Čapka „R.U.R.” z 1920 roku; wywodzi się od słowa oznaczającego pracę przymusową, pańszczyznę.",
 js:"Słowo, które jeden język pożyczył od innego.",
 jl:"Języki pożyczają od siebie słowa, tak jak koledzy pożyczają kredki. Polski pożyczył pizzę z włoskiego, kangura z języka mieszkańców Australii, a karate z japońskiego. Takie słowa to zapożyczenia.",
 jx:"Czy wiesz, że słowo „kawa” to zapożyczenie z tureckiego?"},
{id:"g_mnemonic",cat:"gen",t:"Mnemotechnika",
 s:"Sposób ułatwiający zapamiętywanie, na przykład rymowanka, zdanie lub skojarzenie.",
 l:"Mnemotechniki łączą trudne do zapamiętania informacje z czymś łatwiejszym: rymem, zabawnym zdaniem, obrazem albo wzorem. Zdania, w których pierwsze litery słów odpowiadają kolejnym elementom, pomagają zapamiętać na przykład kolejność planet. Rymowanki pomagają w ortografii, a liczenie na kostkach dłoni pokazuje, które miesiące mają trzydzieści jeden dni. Mnemotechniki działają, bo mózg łatwiej zapamiętuje historie, obrazy i rytm niż suche listy.",
 x:"Kolejność planet zapamiętała dzięki mnemotechnice ze zdaniem o mamie.",
 f:"Nazwa pochodzi z greki, a starożytni Grecy czcili boginię pamięci Mnemosyne, uważaną za matkę muz.",
 js:"Sprytny sposób, żeby coś łatwiej zapamiętać.",
 jl:"Mnemotechnika to sztuczka na pamięć. Może to być piosenka, rymowanka albo zabawne zdanie. Na przykład zdanie Mama Wczoraj Zrobiła Mi Jajecznicę, Siostra Upiekła Naleśniki pomaga zapamiętać kolejność planet od Merkurego do Neptuna.",
 jx:"Wymyśliłam mnemotechnikę, żeby zapamiętać kolejność planet."},
{id:"g_pl_per_pan",cat:"gen",only:1,c:"Polska",t:"Pan, pani i przejście na ty",
 s:"Polskie formy grzecznościowe zwracania się do dorosłych oraz zwyczaj umawiania się na mówienie sobie po imieniu.",
 l:"Po polsku do obcych dorosłych, przełożonych czy nauczycieli zwracamy się zwykle formą pan lub pani z czasownikiem w trzeciej osobie, na przykład czy może mi pan pomóc. Mówienie na ty jest zarezerwowane dla rodziny, przyjaciół, dzieci i rówieśników, choć w wielu firmach i wśród młodych ludzi staje się coraz powszechniejsze. Zwykle to osoba starsza lub stojąca wyżej proponuje przejście na ty. Zbyt szybkie mówienie na ty bywa odbierane jako niegrzeczne, a zbyt długie trzymanie się formy pan jako chłód.",
 x:"Po roku wspólnej pracy szefowa zaproponowała: mówmy sobie po imieniu.",
 f:"Dawniej przejście na ty pieczętowano bruderszaftem, toastem ze splecionymi rękami; nazwa pochodzi od niemieckiego Brüderschaft, czyli braterstwo.",
 js:"Jak grzecznie mówić do dorosłych po polsku: proszę pana, proszę pani.",
 jl:"Do kolegów mówimy po imieniu, na ty. Do obcych dorosłych, na przykład pani w sklepie albo pana kierowcy, mówimy grzecznie: proszę pani, proszę pana. Do nauczycielki w szkole też mówimy: proszę pani.",
 jx:"Przepraszam, czy może mi pan powiedzieć, która godzina?"},
/* ---------- PSYCHOLOGIA (+6) ---------- */
{id:"p_cognitive_load",cat:"psy",t:"Obciążenie poznawcze",
 s:"Ilość wysiłku umysłowego, jaki w danej chwili angażuje pamięć robocza.",
 l:"Pamięć robocza może jednocześnie utrzymać i przetwarzać tylko kilka elementów. Gdy zadanie wymaga zbyt wiele naraz, na przykład nowych informacji, nieczytelnego układu, hałasu w tle i presji czasu, obciążenie poznawcze rośnie i uczenie się lub wykonanie zadania się pogarsza. Nauczyciele i projektanci zmniejszają je, dzieląc zadanie na kroki, podając jasne przykłady, usuwając rozpraszacze i umieszczając powiązane informacje obok siebie. Osoby z ADHD, lękiem albo po prostu zmęczone mogą szybciej osiągać przeciążenie, więc mniejsze obciążenie pomaga wszystkim.",
 x:"Podzielenie polecenia na trzy krótkie kroki zmniejszyło obciążenie poznawcze uczniów.",
 f:"Teorię obciążenia poznawczego rozwinął australijski psycholog edukacyjny John Sweller pod koniec lat osiemdziesiątych dwudziestego wieku.",
 js:"Ile pracy myślowej twój mózg wykonuje w jednej chwili.",
 jl:"Twój mózg może trzymać w głowie tylko kilka rzeczy naraz. Jeśli dzieje się za dużo, na przykład trudne zadanie, hałas i ktoś do ciebie mówi, robi się pełny i zmęczony. Robienie jednego małego kroku naraz bardzo pomaga.",
 jx:"Wyłączyłem telewizor przy lekcjach, żeby mój mózg nie był tak zajęty."},
{id:"p_pareidolia",cat:"psy",t:"Pareidolia",
 s:"Skłonność do dostrzegania znaczących kształtów, zwłaszcza twarzy, w przypadkowych rzeczach, takich jak chmury czy gniazdka elektryczne.",
 l:"Pareidolia pojawia się, gdy mózg widzi znajomy wzór tam, gdzie nikt go nie zaplanował: twarz w przodzie samochodu, zwierzę w chmurze, uśmiech na kromce chleba. Nasz układ wzrokowy bardzo szybko wykrywa twarze, co ma sens u istot społecznych: lepiej pomylić kamień z twarzą, niż przeoczyć prawdziwą. Pareidolia jest całkowicie normalna i powszechna. Działa też w świecie dźwięków, gdy ludzie słyszą słowa w przypadkowym szumie albo w piosenkach puszczonych od tyłu.",
 x:"Przez pareidolię dwa okna i drzwi sprawiały, że dom wyglądał na zdziwiony.",
 f:"Nazwa pochodzi z greki: para znaczy obok lub błędnie, a eidolon to obraz, kształt.",
 js:"Widzenie twarzy albo kształtów w chmurach, gniazdkach i innych rzeczach.",
 jl:"Czy widziałeś kiedyś twarz w chmurze albo gniazdko, które wygląda na przestraszone? Nasz mózg tak świetnie znajduje twarze, że widzi je wszędzie. To pareidolia i zdarza się każdemu.",
 jx:"Na spacerze bawiliśmy się w szukanie twarzy w drzewach i płotach."},
{id:"p_bystander_effect",cat:"psy",t:"Efekt widza",
 s:"Zjawisko polegające na tym, że w obecności innych ludzi często rzadziej pomagamy komuś w nagłej sytuacji.",
 l:"Gdy wiele osób widzi kogoś w kłopocie, każda może zakładać, że ktoś inny zareaguje, albo patrząc na spokojne twarze innych, uznać, że nic poważnego się nie dzieje. Odpowiedzialność rozkłada się na wszystkich i słabnie. Znajomość tego efektu pomaga go przełamać: dobrze jest zwrócić się do konkretnej osoby, na przykład pan w zielonej kurtce, proszę zadzwonić po pomoc. Późniejsze badania pokazują, że w prawdziwych, wyraźnie groźnych sytuacjach świadkowie często jednak pomagają. Zjawisko nazywa się też efektem świadka.",
 x:"Pamiętając o efekcie widza, nie czekała na innych i od razu ruszyła z pomocą.",
 f:"W słynnym eksperymencie z 1968 roku Bibb Latané i John Darley wpuszczali do pokoju nieszkodliwy dym i odkryli, że osoby same zgłaszały go znacznie częściej niż te, które siedziały z innymi, ignorującymi dym.",
 js:"Kiedy ludzie w grupie nie pomagają, bo myślą, że zrobi to ktoś inny.",
 jl:"Czasem, kiedy wiele osób widzi, że ktoś potrzebuje pomocy, wszyscy czekają, bo myślą, że pomoże ktoś inny. Naukowcy nazywają to efektem widza. Możesz go pokonać: gdy widzisz, że ktoś się zranił albo jest smutny, od razu powiedz dorosłemu.",
 jx:"Kiedy chłopiec przewrócił się na boisku, Ela nie czekała, tylko pobiegła po nauczyciela."},
{id:"p_window_of_tolerance",cat:"psy",t:"Okno tolerancji",
 s:"Zakres pobudzenia, w którym człowiek może przeżywać emocje, a jednocześnie jasno myśleć i radzić sobie.",
 l:"W oknie tolerancji możemy czuć stres, smutek czy ekscytację, a mimo to myśleć, uczyć się i nawiązywać kontakt z innymi. Zbyt silne pobudzenie wypycha nas ponad okno, w stan nadmiernego pobudzenia, czyli paniki, złości czy gonitwy myśli; zbyt słabe – poniżej, w stan obniżonego pobudzenia, czyli odrętwienia, wyłączenia się czy poczucia oddalenia. Stres, trauma, choroba i brak snu mogą okno zawęzić. Uziemianie, spokojny oddech, ruch, odpoczynek i bezpieczne relacje pomagają do niego wrócić, a z czasem je poszerzyć.",
 x:"Terapeutka wyjaśniła jej na przykładzie okna tolerancji, dlaczego czasem zamiera podczas kłótni.",
 f:"Pojęcie wprowadził amerykański psychiatra Daniel Siegel w książce „The Developing Mind” wydanej w 1999 roku.",
 js:"Spokojna strefa, w której możesz myśleć, nawet gdy masz duże uczucia.",
 jl:"Wyobraź sobie okno. Kiedy jesteś w środku, możesz czuć różne rzeczy i dalej myśleć i rozmawiać. Gdy uczucia są za duże, możesz krzyczeć albo panikować; gdy się wyłączasz, czujesz się jak zamrożony. Głębokie oddechy, przytulenie albo cichy kącik pomagają wrócić do okna.",
 jx:"Kiedy wszystko jest za bardzo, siadam w kąciku spokoju, aż wrócę do swojego okna."},
{id:"p_halo_effect",cat:"psy",t:"Efekt aureoli",
 s:"Błąd myślenia, w którym jedna pozytywna cecha osoby lub rzeczy wpływa na ocenę wszystkich jej pozostałych cech.",
 l:"Jeśli ktoś jest atrakcyjny, pewny siebie albo sławny, zwykle zakładamy, że jest też miły, mądry i godny zaufania, choć nie mamy na to dowodów. Podobnie z produktami: modna marka wydaje się lepszej jakości. Efekt aureoli, zwany też efektem halo, może wpływać na rozmowy kwalifikacyjne, oceny szkolne, wybory i zakupy. Odwrotne zjawisko, gdy jedna negatywna cecha psuje ocenę całości, bywa nazywane efektem diabelskich rogów. Pomaga stosowanie jasnych kryteriów i sprawdzanie faktów.",
 x:"Przez efekt aureoli rekruterzy wysoko ocenili czarującego kandydata we wszystkich umiejętnościach.",
 f:"Psycholog Edward Thorndike opisał to zjawisko w 1920 roku, gdy zauważył, że oficerowie oceniali żołnierzy albo jako dobrych we wszystkim, albo jako słabych we wszystkim.",
 js:"Kiedy jedna fajna cecha kogoś sprawia, że myślisz, że wszystko w nim jest super.",
 jl:"Czasem poznajemy kogoś bardzo zabawnego i od razu myślimy, że na pewno jest też mądry, miły i świetnie gra w piłkę. A to nie zawsze prawda! Ten błąd to efekt aureoli, jak błyszcząca obręcz nad głową anioła, która sprawia, że wszystko wygląda lepiej.",
 jx:"Nowy kolega świetnie rysował, a my przez efekt aureoli myśleliśmy, że będzie też najlepszy z matmy."},
{id:"p_pl_116111",cat:"psy",only:1,c:"Polska",t:"Telefon zaufania 116 111",
 s:"Bezpłatny telefon zaufania dla dzieci i młodzieży w Polsce, gdzie można porozmawiać o każdym problemie.",
 l:"Pod numer 116 111 mogą dzwonić dzieci i nastolatki, gdy coś je martwi, smuci albo przestrasza: kłótnie w domu, kłopoty w szkole, samotność, przemoc rówieśnicza czy po prostu potrzeba rozmowy. Odbierają przeszkoleni konsultanci, którzy słuchają bez oceniania i pomagają znaleźć rozwiązanie. Rozmowa jest bezpłatna, a z konsultantami można też kontaktować się przez stronę internetową. Telefon prowadzi Fundacja Dajemy Dzieciom Siłę. W sytuacji zagrożenia życia trzeba dzwonić pod numer alarmowy 112.",
 x:"Kiedy nie umiała porozmawiać z rodzicami, zadzwoniła pod 116 111 i poczuła ulgę.",
 f:"Numery zaczynające się od 116 to wspólne europejskie numery dla usług społecznych, więc pod 116 111 w wielu krajach Unii Europejskiej działa telefon zaufania dla dzieci.",
 js:"Numer, pod który dziecko może zadzwonić za darmo, kiedy jest mu smutno lub źle.",
 jl:"Czasem dzieje się coś, o czym trudno powiedzieć. Wtedy możesz porozmawiać z zaufanym dorosłym: rodzicem, nauczycielem albo panią pedagog. Możesz też za darmo zadzwonić pod numer 116 111. Ktoś miły wysłucha cię i pomoże.",
 jx:"Na tablicy w szkole wisi plakat z numerem 116 111."},
/* ---------- BIZNES (+6) ---------- */
{id:"b_freelancer",cat:"biz",t:"Freelancer",
 s:"Osoba, która pracuje na własny rachunek dla wielu klientów przy osobnych zleceniach, zamiast być zatrudnioną w jednej firmie.",
 l:"Freelancerzy, czyli wolni strzelcy, na przykład graficy, tłumacze, pisarze, fotografowie czy programiści, sami szukają klientów, ustalają stawki i decydują, ile pracy biorą. Daje to swobodę i różnorodność, ale też niepewność: dochody mogą się zmieniać z miesiąca na miesiąc, a podatki, emerytura i urlop są na ich głowie. W Polsce freelancerzy często prowadzą jednoosobową działalność gospodarczą albo pracują na umowach cywilnoprawnych. Wielu znajduje zlecenia przez platformy internetowe.",
 x:"Jako freelancer projektuje logo dla małych firm w trzech krajach.",
 f:"Angielskie słowo pochodzi od wyrażenia free lance, którego Walter Scott użył w powieści „Ivanhoe” z 1819 roku na określenie średniowiecznego najemnika, którego kopię mógł wynająć każdy.",
 js:"Ktoś, kto pracuje sam dla różnych ludzi, a nie dla jednego szefa.",
 jl:"Większość dorosłych pracuje w jednej firmie. Freelancer pracuje sam dla siebie i wykonuje zlecenia dla wielu różnych osób. Na przykład ilustratorka może jednego miesiąca rysować do książki, a następnego do strony internetowej.",
 jx:"Moja ciocia jest freelancerką i rysuje ilustracje do książek dla dzieci w swojej kuchni."},
{id:"b_logo",cat:"biz",t:"Logo",
 s:"Znak graficzny, symbol lub stylizowana nazwa, po których rozpoznaje się firmę, produkt lub organizację.",
 l:"Logo to wizualna twarz marki. Może być obrazkiem, na przykład jabłkiem czy ptakiem, stylizowanym napisem albo połączeniem obu. Dobre logo jest proste, czytelne nawet w małym rozmiarze, działa w jednym kolorze i pasuje do charakteru organizacji. Firmy chronią swoje logo jako znak towarowy i ustalają zasady jego używania. Logo to tylko część marki, na którą składają się też reputacja, wartości i doświadczenia klientów. W języku polskim słowo logo zwykle się nie odmienia.",
 x:"Nowe logo piekarni to uśmiechnięty bochenek chleba.",
 f:"Znak firmy Nike, zwany swoosh, zaprojektowała w 1971 roku studentka grafiki Carolyn Davidson, która dostała za niego trzydzieści pięć dolarów.",
 js:"Mały obrazek albo znak, który pokazuje, z jakiej firmy coś pochodzi.",
 jl:"Logo to specjalny obrazek albo napis, którego firma używa, żeby ludzie ją rozpoznawali. Logo znajdziesz na butach, pudełkach płatków i sklepach. Niektóre są tak znane, że wiesz, o jaką firmę chodzi, widząc tylko obrazek.",
 jx:"Na szkolny festyn zaprojektowaliśmy logo ze słońcem i książką."},
{id:"b_agenda",cat:"biz",t:"Agenda spotkania",
 s:"Lista tematów do omówienia lub zadań do wykonania podczas spotkania, zwykle w ustalonej kolejności.",
 l:"Agenda, nazywana też porządkiem obrad, mówi uczestnikom, po co jest spotkanie, co będzie omawiane, w jakiej kolejności i często jak długo. Wysłana wcześniej pozwala się przygotować, przynieść dokumenty i zgłosić dodatkowe punkty. Podczas spotkania prowadzący pilnuje, by rozmowa trzymała się agendy. Często na końcu jest punkt sprawy różne lub wolne wnioski. W polszczyźnie agenda bywa też nazwą oddziału jakiejś instytucji, na przykład agendy ONZ.",
 x:"Prześlij mi swoje punkty do piątku, to dopiszę je do agendy.",
 f:"Agenda to łacińskie słowo oznaczające rzeczy, które trzeba zrobić.",
 js:"Lista spraw, o których będzie się rozmawiać na spotkaniu.",
 jl:"Kiedy dorośli mają zebranie, często najpierw zapisują listę: o czym porozmawiają i w jakiej kolejności. Taka lista to agenda. Dzięki niej nikt nie zbacza z tematu i nic nie zostaje zapomniane.",
 jx:"Agenda samorządu szkolnego miała trzy punkty: boisko, bibliotekę i kiermasz ciast."},
{id:"b_prototype",cat:"biz",t:"Prototyp",
 s:"Wczesny model lub próbna wersja produktu, zbudowana po to, by sprawdzić pomysł przed wykonaniem wersji ostatecznej.",
 l:"Prototyp może być prosty jak szkic aplikacji na papierze, model z kartonu czy część wydrukowana w 3D, albo zaawansowany jak jeżdżący samochód, którego jeszcze nie ma w sprzedaży. Służy do szybkiej i taniej nauki: czy to działa, czy ludzie to rozumieją, co się psuje? Projektanci często budują wiele prototypów, ulepszając każdy na podstawie testów i opinii. Prototyp różni się od MVP, czyli minimalnej wersji produktu, którą faktycznie udostępnia się klientom.",
 x:"Zespół przetestował kartonowy prototyp nowego krzesła z dwudziestoma użytkownikami.",
 f:"Słowo pochodzi z greki: protos znaczy pierwszy, a typos – odcisk, wzór.",
 js:"Pierwszy, próbny model czegoś nowego.",
 jl:"Zanim wynalazcy zrobią coś na serio, robią pierwszą próbę, czyli prototyp. Może być z kartonu, taśmy albo klocków. Testują go, sprawdzają, co nie działa, i go ulepszają.",
 jx:"Nasz prototyp karmnika dla ptaków był zrobiony z kartonu po soku i sznurka."},
{id:"b_barcode",cat:"biz",t:"Kod kreskowy",
 s:"Wzór z kresek lub kwadratów, który urządzenie może zeskanować, by szybko rozpoznać produkt.",
 l:"Tradycyjny kod kreskowy to rząd czarnych kresek i białych odstępów o różnej szerokości, które zapisują liczbę. Gdy czytnik przy kasie go odczyta, komputer wyszukuje nazwę i cenę produktu oraz aktualizuje stan magazynu. Przyspiesza to obsługę i zmniejsza liczbę pomyłek. Kody dwuwymiarowe, takie jak kody QR, mieszczą znacznie więcej informacji w siatce kwadratów i można je skanować aparatem telefonu. Numer pod kodem kreskowym identyfikuje produkt, a nie jego cenę.",
 x:"Kasa samoobsługowa piszczała przy każdym zeskanowanym kodzie kreskowym.",
 f:"Pierwszym produktem sprzedanym dzięki zeskanowaniu standardowego kodu kreskowego była paczka gumy do żucia w supermarkecie w amerykańskim stanie Ohio w 1974 roku.",
 js:"Paski na rzeczach, które kupujesz, odczytywane przez maszynę przy kasie.",
 jl:"Spójrz na pudełko płatków, a znajdziesz czarno-białe paski z cyframi. To kod kreskowy. W sklepie maszyna piszczy, kiedy odczyta paski, i od razu wie, co to za produkt i ile kosztuje.",
 jx:"W supermarkecie pomagałem mamie skanować kody kreskowe przy kasie samoobsługowej."},
{id:"b_pl_umowa_zlecenie",cat:"biz",only:1,c:"Polska",t:"Umowa zlecenie",
 s:"Umowa cywilnoprawna, w której jedna strona zobowiązuje się wykonać dla drugiej określone czynności, bez stosunku pracy.",
 l:"Umowę zlecenie reguluje Kodeks cywilny, a nie Kodeks pracy, dlatego zleceniobiorca nie ma wielu praw pracowniczych, takich jak płatny urlop wypoczynkowy czy okres wypowiedzenia na zasadach z Kodeksu pracy. Zwykle odprowadza się od niej składki na ubezpieczenia społeczne, choć są wyjątki, na przykład dla uczniów i studentów do dwudziestego szóstego roku życia. Od 2017 roku obowiązuje minimalna stawka godzinowa dla większości zleceń. Umowa zlecenie różni się od umowy o dzieło, w której liczy się konkretny rezultat.",
 x:"W wakacje pracowała w kawiarni na umowie zlecenie.",
 f:"Poprawna nazwa prawnicza to umowa zlecenia, a forma umowa zlecenie jest potoczna, choć bardzo rozpowszechniona.",
 js:"Rodzaj umowy, na podstawie której ktoś wykonuje dla kogoś pracę, ale nie jest zwykłym pracownikiem.",
 jl:"Niektórzy dorośli mają w pracy umowę o pracę, a inni umowę zlecenie. Przy umowie zlecenie umawiają się, że zrobią dla kogoś jakieś zadania, na przykład poprowadzą zajęcia albo popilnują sklepu. Często takie umowy podpisują studenci w wakacje.",
 jx:"Mój starszy brat w wakacje prowadził zajęcia na półkoloniach na umowie zlecenie."}
]);
